package com.vision.iptv;
import java.io.*;import java.net.*;import java.util.*;import java.text.*;import java.util.zip.GZIPInputStream;import android.util.Xml;import org.xmlpull.v1.XmlPullParser;
final class Epg {
 static class Programme {String title="",description="";long start,end;}
 final Map<String,List<Programme>> entries=new HashMap<>();
 static long time(String value){if(value==null)return 0;try{String s=value.trim();SimpleDateFormat f=new SimpleDateFormat(s.length()>14?"yyyyMMddHHmmss Z":"yyyyMMddHHmmss",Locale.US);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.parse(s).getTime();}catch(Exception e){return 0;}}
 static Epg load(String address)throws Exception{URL url=new URL(address);if(!url.getProtocol().equals("http")&&!url.getProtocol().equals("https"))throw new IOException("HTTP(S) only");URLConnection c=url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);Epg epg=new Epg();try(BufferedInputStream raw=new BufferedInputStream(c.getInputStream())){raw.mark(2);int a=raw.read(),b=raw.read();raw.reset();InputStream in=a==31&&b==139?new GZIPInputStream(raw):raw;XmlPullParser p=Xml.newPullParser();p.setInput(in,null);Programme item=null;String channel=null;long now=System.currentTimeMillis();int count=0;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String tag=p.getName();if(tag.equals("programme")){item=new Programme();channel=p.getAttributeValue(null,"channel");item.start=time(p.getAttributeValue(null,"start"));item.end=time(p.getAttributeValue(null,"stop"));}else if(item!=null&&tag.equals("title"))item.title=p.nextText();else if(item!=null&&tag.equals("desc"))item.description=p.nextText();}else if(event==XmlPullParser.END_TAG&&p.getName().equals("programme")&&item!=null){if(channel!=null&&item.end>now-86400000L&&item.start<now+604800000L){epg.entries.computeIfAbsent(channel,k->new ArrayList<>()).add(item);if(++count>300000)throw new IOException("EPG too large");}item=null;}}}for(List<Programme> l:epg.entries.values())l.sort(Comparator.comparingLong(x->x.start));return epg;}
 List<Programme> forChannel(String id){return entries.getOrDefault(id,Collections.emptyList());}
 Programme current(String id){long now=System.currentTimeMillis();for(Programme p:forChannel(id))if(p.start<=now&&p.end>now)return p;return null;}
}